#include <stdlib.h>
#include <string.h>
typedef struct N212{struct N212*c[26];char*word;}N212;static N212*nn(){return calloc(1,sizeof(N212));}static void dfs(char**b,int m,int n,int i,int j,N212*p,char***o,int*c,int*cap){if(i<0||j<0||i>=m||j>=n||b[i][j]=='#')return;int k=b[i][j]-'a';p=p->c[k];if(!p)return;if(p->word){if(*c==*cap){*cap*=2;*o=realloc(*o,*cap*sizeof(char*));}(*o)[(*c)++]=p->word;p->word=NULL;}char ch=b[i][j];b[i][j]='#';dfs(b,m,n,i+1,j,p,o,c,cap);dfs(b,m,n,i-1,j,p,o,c,cap);dfs(b,m,n,i,j+1,p,o,c,cap);dfs(b,m,n,i,j-1,p,o,c,cap);b[i][j]=ch;}char** findWords(char**b,int m,int*cols,char**w,int ws,int*rs){N212*r=nn();for(int x=0;x<ws;x++){N212*p=r;for(int i=0;w[x][i];i++){int k=w[x][i]-'a';if(!p->c[k])p->c[k]=nn();p=p->c[k];}p->word=w[x];}int cap=16,c=0;char**o=malloc(cap*sizeof(char*));for(int i=0;i<m;i++)for(int j=0;j<cols[0];j++)dfs(b,m,cols[0],i,j,r,&o,&c,&cap);*rs=c;return o;}
